    // ═══ 인트로 컷신 게이트 (2026-07-27): 컷신 재생 중/예정이면 cutscene_* 키 외 전부 차단 ═══
    // (부팅 자동재생 + autoplay 차단 후 첫 클릭 지연재생(_pending)까지 모두 원천 차단 — 전쟁 서사는 보이스 전용)
    if(typeof key==='string'&&key.indexOf('cutscene_')!==0){try{
      const _cutBlock=(typeof _cutsceneState!=='undefined'&&_cutsceneState==='INTRO_CUTSCENE')
        ||(typeof _forceCutscene!=='undefined'&&_forceCutscene&&!(G&&G._cutsceneDone))
        ||(typeof G!=='undefined'&&G&&G.stage===0&&!G._cutsceneDone&&!G.on);
      if(_cutBlock)return;
    }catch(e){}}
    if(!force&&OPT.bgmTrack&&OPT.bgmTrack.startsWith('t:'))return;
    if(!force&&OPT.bgmTrack!=='auto'&&OPT.bgmTrack!=='allRandom'&&key!=='death'&&key!=='victory'&&key!=='forge'&&key!==OPT.bgmTrack)return;
    this.stop();
    this._curKey=key;
    let src=null;
    if(this._isActKey(key)&&OPT.bgmTrack==='auto'){
      // 장 진입마다 played set 초기화 → 장 BGM 먼저
      this._playedSets[key]=new Set();this._actDone[key]=false;
      src=this._pickActFirst(key);if(!src)src=this._pickMixed(key);
    }else if(OPT.bgmTrack==='allRandom'&&key!=='death'&&key!=='victory'&&key!=='forge'&&!key.startsWith('cutscene_')){
      src=this._pickAllRandom();
    }else{
      src=this._pickRandom(key);
    }
    if(!src)return;
    this._lastSrc=src;
    const a=this._getAudio(src);
    if(_ultMuted){BGM._savedVol=this._vol;a.volume=0}else a.volume=this._vol;a.currentTime=0;a.loop=false;
    a.onended=(key==='death'||key==='victory')?null:this._onEnded;
    const _playGeneration=this._playGeneration;
    a.play().catch(()=>{
      if(this._playGeneration!==_playGeneration||this._cur!==a)return;
      this._pending=key;
      if(!this._bound){this._bound=true;['click','keydown','pointerdown','touchstart','mousemove'].forEach(e=>document.addEventListener(e,BGM._onInteract,{passive:true}))}
    });
    this._cur=a;
  }

playTrack(src){
    // 개별 트랙 직접 재생 (드롭다운 t: 접두사)
    this.stop();
    this._curKey='_track';
    this._lastSrc=src;
    const a=this._getAudio(src);
    if(_ultMuted){BGM._savedVol=this._vol;a.volume=0}else a.volume=this._vol;
    a.currentTime=0;
    a.loop=true;
    a.onended=null;
    const _playGeneration=this._playGeneration;
    a.play().catch(()=>{
      if(this._playGeneration!==_playGeneration||this._cur!==a)return;
      this._pending='_track';
      if(!this._bound){this._bound=true;['click','keydown','pointerdown','touchstart','mousemove'].forEach(e=>document.addEventListener(e,BGM._onInteract,{passive:true}))}
    });
    this._cur=a;
  }

_getAudio(src){
    if(!this._cache[src]){const a=new Audio(src);a.preload='auto';a.onerror=()=>{BGM._badSrcs[src]=1;delete BGM._cache[src];const i=BGM._cacheLRU.indexOf(src);if(i>=0)BGM._cacheLRU.splice(i,1);if(BGM._cur===a){const _failedKey=BGM._curKey,_failedGeneration=BGM._playGeneration;BGM._cur=null;setTimeout(()=>{if(BGM._cur===null&&BGM._curKey===_failedKey&&BGM._playGeneration===_failedGeneration)BGM._onEnded()},300)}};this._cache[src]=a}
    const li=this._cacheLRU.indexOf(src);if(li>=0)this._cacheLRU.splice(li,1);this._cacheLRU.push(src);
    while(this._cacheLRU.length>this._CACHE_MAX){
      const idx=this._cacheLRU.findIndex(s=>this._cache[s]!==this._cur); // 재생 중 트랙은 축출 제외
      if(idx<0)break;
      const old=this._cacheLRU.splice(idx,1)[0],oa=this._cache[old];
      if(oa){oa.pause();oa.removeAttribute('src');oa.load()}
      delete this._cache[old];
    }
    return this._cache[src];
  }

_onEnded(){
    const key=BGM._curKey;if(!key)return;
    let src=null;
    if(BGM._isActKey(key)&&OPT.bgmTrack==='auto'){
      // 장 BGM 미소진: 미재생 트랙 중 선택 / 소진 후: 전체 랜덤
      src=BGM._actDone[key]?BGM._pickAllRandom():BGM._pickActFirst(key);
      if(!src)src=BGM._pickAllRandom(); // pickActFirst가 null(막 소진) → 즉시 전체 랜덤
    }else if(OPT.bgmTrack==='allRandom'){src=BGM._pickAllRandom();}
    else{src=BGM._pickRandom(key);}
    if(!src)return;
    BGM._lastSrc=src;
    const a=BGM._getAudio(src);
    if(_ultMuted){BGM._savedVol=BGM._vol;a.volume=0}else a.volume=BGM._vol;a.currentTime=0;a.loop=false;a.onended=(key==='death'||key==='victory')?null:BGM._onEnded;
    const _playGeneration=BGM._playGeneration;
    a.play().catch(()=>{
      if(BGM._playGeneration!==_playGeneration||BGM._cur!==a)return;
      BGM._pending=key;
      if(!BGM._bound){BGM._bound=true;['click','keydown','pointerdown','touchstart','mousemove'].forEach(e=>document.addEventListener(e,BGM._onInteract,{passive:true}))}
    });BGM._cur=a;
  }

function _fallenResolve(){
  // 카운트다운 종료 → 부활 or 사망
  if(P._fallenCanRevive&&P._fallenRevRoll<P._fallenRevChance){
    // ── 악마화 부활 성공! ──
    P._demonRevCd=P._fallenRevCdFrames;
    // 부활 성공 시 모든 전투 자원을 최대치로 복원한다.
    P.hp=P.mhp;P.mp=P.mmp;P.st=P.mst;
    P.s='idle';P.st2=0;P.iframes=120; // 2초 무적
    G._flashT=12;G._flashCol='#ff0000';G.shake=20*OPT.shake/100;G.slowMo=30;
    SFX.levelup();playSample('voice_demon_revive',1,_r(1,.1));
    addTxt(P.x,P.y-50,_T('악마화 부활!'),'#ff2200',120);
    addTxt(P.x,P.y-25,_T('부활력 ')+P._fallenRevChance+'%','#ff8844',50);
    if(P.lv<=500)_petSayCD('revive_tip','cat','데미지 부족하면 무기 강화!',5,30,'crow','G키 대장간. 강화 안 하면 계속 죽어.',4);
    if(typeof _petOnDeath==='function')_petOnDeath();
    for(let k=0;k<30;k++){const a=Math.PI*2*k/30;poolPart(P.x,P.y,Math.cos(a)*8,Math.sin(a)*8,k%2===0?'#ff0000':'#ff8800',5,20)}
    return;
  }
  // ── 부활 실패 → 진짜 사망 ──
  _ddDeaths++;{const _ddH=(typeof SI_TO_HELL!=='undefined'&&SI_TO_HELL[G.stage]!=null)?SI_TO_HELL[G.stage]:0;_ddChapDeathMap[_ddH]=(_ddChapDeathMap[_ddH]||0)+1}
  P.s='dead';P.iframes=0;if(G._sStats)G._sStats.deaths++;
  SFX.die();G.on=false;G._ebBomb=null;G._mmBomb=null;G._gsBombs=[];G._bsBombs=[];G._boneWalls=[];G._fireZones=[];G._stProjs=[];G._gwLightning=null;G._voidScarecrow=null;G._ancestorReturns=[];G._ancestors=[];
  const _deathMusicGeneration=_ddDeaths;BGM.fadeOut(500);setTimeout(()=>{if(_ddDeaths===_deathMusicGeneration&&P.s==='dead'&&!G.on)BGM.play('death')},600);
  ['hud','hudTop','hudCorner','mmWrap','skBar','mmLvl','globeHP','globeMP'].forEach(id=>$(id).classList.remove('on'));
  const expLoss=~~(P.exp*0.3);
  const _hn=_T(HELL_NAMES[STG[G.stage].hell]);
  $('retryBtn').textContent=G._bossArena&&_isDruidFinale({ib:true})?_L('보스 재도전','Retry Boss'):_T('다시 일어서라');
  const infoTxt=`💀 ${G.kills} `+_L('처치','kills')+` | ${_hn} | EXP -${expLoss} | 🔥 `+_L('최대콤보','Max Combo')+` ${G.comboMax}`;
  // 피해 로그 렌더 (오른쪽 사이드)
  let _dlHtml='';
  if(_dmgLog.length){
    for(let _di=0;_di<_dmgLog.length;_di++){
      const d=_dmgLog[_di];
      const _isLast=_di===_dmgLog.length-1;
      const _col=_isLast?'#ff2222':'#cc6644';
      const _sz=_isLast?'1.3rem':'1rem';
      _dlHtml+=`<div style="color:${_col};font-size:${_sz};font-weight:${_isLast?'900':'400'}">-${d.final} <span style="color:#887766;font-size:.8rem">${d.src}</span></div>`;
    }
    _dlHtml+=`<div style="color:#886644;font-size:.85rem;margin-top:4px;border-top:1px solid #442211;padding-top:4px">${_T('맞아서 사망')}</div>`;
  }
  $('dInfo').textContent=infoTxt;
  $('dDmgLog').innerHTML=_dlHtml;
  $('deathReplayBtn').disabled=_drLen===0;
  $('death').classList.add('on');
  _deathDlgStart(); // 두 펫 동시 대사 로테이션 시작
}
